using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;
public static class CPCFormal {
 [Serializable]class Rule{public int seed,wave;public bool treasure,boss;public string gear,streams;}
 [Serializable]class Rules{public Rule[] rows;}
 [Serializable]class Gear{public string definition;public int type,quality;public float attack,defense;public int[] affixes;}
 [Serializable]class Drop{public string actualId,semantic;public int kind,amount;}
 [Serializable]class Result{public string targetId,run,region,seed,randomBefore,randomAfter,globalBefore,globalAfter,bagBefore,bagAfter;public int wave,xpBefore,xpAfter,levelBefore,levelAfter;public Drop[] drops;}
 static string Sig(GearItem g)=>g==null?"MATERIAL":JsonUtility.ToJson(new Gear{definition=g.definitionId,type=(int)g.type,quality=(int)g.quality,attack=g.Attack,defense=g.Defense,affixes=g.affixes});
 public static IEnumerator Run(CPCProbe p){yield return p.Wait(()=>GameEntry.Instance!=null,12);var entry=GameEntry.Instance;entry.Refresh();bool continued=entry.Info.canContinue;if(continued)p.Check("formal-continue",entry.Continue(),"existing genuine product checkpoint");else{entry.AskNew();p.Check("formal-confirm-new",entry.ConfirmNew(),"actual new game confirmation path");}yield return p.Wait(()=>UnityEngine.Object.FindFirstObjectByType<CombatSession>()?.Saves?.IsInitialized==true,30);var s=UnityEngine.Object.FindFirstObjectByType<CombatSession>();if(s?.Saves?.IsInitialized!=true)throw new Exception("Formal save/session not initialized");if(s.Flow.ActiveRun==null)p.Check("formal-depart",s.Flow.Depart(AdventureMode.ForestExploration),"actual Forest departure transaction");yield return p.Wait(()=>s.WorldReady&&s.Flow.ActiveRun!=null,30);if(!s.WorldReady)throw new Exception("Formal world readiness");foreach(var e in s.enemies)e.enabled=false;Time.timeScale=0;p.Check("formal-no-training-scope",p.Baseline||CPCProbe.ContextCount()==0,"no training registration in actual Run");p.Check("formal-real-running-forest",s.Flow.ActiveRun.mode==AdventureMode.ForestExploration&&s.Flow.ActiveRun.hasRandomStreams,"normal generated/restored world");
  p.Check("formal-save-v9",JsonUtility.FromJson<CombatSaveEnvelope>(File.ReadAllText(s.Saves.SavePath)).version==9,"genuine restored envelope, no schema change");
  if(!p.Baseline){var obj=new GameObject("Rejected training scope negative");var type=typeof(CombatEnemy).Assembly.GetType("TrainingLootContext");var ctx=obj.AddComponent(type);bool refused=false;try{type.GetMethod("Initialize").Invoke(ctx,new object[]{19});}catch(System.Reflection.TargetInvocationException e){refused=e.InnerException is InvalidOperationException;}UnityEngine.Object.Destroy(obj);p.Check("formal-context-registration-rejected",refused&&CPCProbe.ContextCount()==0,"actual Run cannot become training scope");}
  // Explicit isolated rule inputs, never persisted or credited as items. Restore original stream object in finally.
  var run=s.Flow.ActiveRun;var original=run.randomStreams;var rules=new List<Rule>();try{foreach(int seed in Enumerable.Range(1,32))foreach(int wave in new[]{0,1,5,45,100})foreach(int variant in new[]{0,1,2}){run.randomStreams=AdventureRandom.Create(seed);var g=AdventureItems.Roll(wave,variant==1,variant==2,s.hero);rules.Add(new Rule{seed=seed,wave=wave,treasure=variant==1,boss=variant==2,gear=Sig(g),streams=JsonUtility.ToJson(run.randomStreams)});}
   var neutral=typeof(AdventureItems).GetMethod("RollTraining");if(neutral!=null){foreach(int seed in Enumerable.Range(1,32)){run.randomStreams=AdventureRandom.Create(seed);string expected=Sig(AdventureItems.Roll(0,owner:s.hero)),state=JsonUtility.ToJson(run.randomStreams);run.randomStreams=AdventureRandom.Create(seed);string actual=Sig((GearItem)neutral.Invoke(null,new object[]{s.hero}));p.Check("neutral-quality-and-draw-order-"+seed,expected==actual&&state==JsonUtility.ToJson(run.randomStreams),"training zero-luck entry, no fictitious Session/Wave");}}
  }finally{run.randomStreams=original;}File.WriteAllText(p.Root+"/formal-rules.json",JsonUtility.ToJson(new Rules{rows=rules.ToArray()},true));p.Check("formal-rule-matrix",rules.Count==480,"32 seeds x5 progression inputs x3 quality branches; not 480 kills");
  if(!continued){p.Check("formal-seed-save",s.Saves.SaveProgress(false),"real v9 initial checkpoint before actual kill");var dest=p.Root+"/SeedPackage";Directory.CreateDirectory(dest);foreach(var f in Directory.GetFiles(Path.GetDirectoryName(s.Saves.SavePath)))File.Copy(f,Path.Combine(dest,Path.GetFileName(f)),false);}
  var target=s.enemies.Where(e=>e.GetComponent<ForestBossBrain>()==null).OrderByDescending(e=>s.enemies.Where(x=>x!=e).Select(x=>Vector3.Distance(e.transform.position,x.transform.position)).DefaultIfEmpty(99).Min()).First();
  var cc=s.hero.GetComponent<CharacterController>();cc.enabled=false;s.hero.transform.position=target.transform.position+Vector3.back*1.3f;cc.enabled=true;s.hero.transform.rotation=Quaternion.identity;s.orbit.enabled=false;s.hero.cameraTransform.position=s.hero.transform.position+new Vector3(0,4,-5);s.hero.cameraTransform.LookAt(target.transform.position+Vector3.up);var combat=s.hero.GetComponent<AdventureCombat>();p.Check("formal-equip-real-sword",combat.Gear.SelectMain(combat.Gear.items.First(x=>x.type==GearType.Sword&&x.InBag)),"real equipment API");Time.timeScale=1;PlayerInput.Focus(true);yield return null;yield return null;float end=Time.realtimeSinceStartup+18;int attacks=0;while(!target.Health.Dead&&Time.realtimeSinceStartup<end){if(s.hero.Progression.IsChoosing)s.hero.Progression.SelectChoice(0);if(combat.Strike())attacks++;yield return null;}p.Check("formal-actual-weapon-death",target.Health.Dead&&attacks>0,"actual sword damage, AI disabled only for controlled paired inputs");if(!target.Health.Dead)throw new Exception("Formal controlled sword did not kill; no direct Damage fallback");Time.timeScale=0;var before=UnityEngine.Object.FindObjectsByType<LootPickup>().ToArray();var result=new Result{targetId=target.entityId,run=run.runId,region=run.regionInstanceId,seed=run.seed.ToString(),wave=s.Wave,randomBefore=JsonUtility.ToJson(run.randomStreams),globalBefore=CPCProbe.Rng(),bagBefore=CPCProbe.Bag(s.hero),xpBefore=s.hero.Progression.Experience,levelBefore=s.hero.Progression.Level};target.DropLootOnce();result.randomAfter=JsonUtility.ToJson(run.randomStreams);result.globalAfter=CPCProbe.Rng();result.bagAfter=CPCProbe.Bag(s.hero);result.xpAfter=s.hero.Progression.Experience;result.levelAfter=s.hero.Progression.Level;var drops=UnityEngine.Object.FindObjectsByType<LootPickup>().Where(x=>!before.Contains(x)).ToArray();result.drops=drops.Select(d=>new Drop{actualId=d.Gear?.id??d.InteractionId,kind=(int)d.Kind,amount=d.Amount,semantic=Sig(d.Gear)}).OrderBy(d=>d.semantic).ThenBy(d=>d.kind).ToArray();File.WriteAllText(p.Root+"/formal-death.json",JsonUtility.ToJson(result,true));for(int i=0;i<5;i++)target.DropLootOnce();p.Check("formal-drop-once",drops.Length>0&&UnityEngine.Object.FindObjectsByType<LootPickup>().Length==before.Length+drops.Length&&result.randomAfter==JsonUtility.ToJson(run.randomStreams)&&result.xpAfter==s.hero.Progression.Experience,"five duplicate calls no extra draws/items/xp");p.Check("formal-ground-not-bag",result.bagBefore==result.bagAfter,"actual material/gear drops remain ground objects");p.Check("formal-global-state",result.globalBefore==result.globalAfter,"Run owns reward stream");
 }
}

